-- Year 4 Sirah, Pelajaran 2: Rasul Ulul Azmi, source pages 29-69 (scan PDF pages 1-41)
-- Jawi-first 6 missions, 24 study cards, 7 games and 36 questions.
INSERT INTO public.learning_units (unit_code, school_year, subject, title, missions, games, published)
VALUES ('sirah_t4_p2',4,'Sirah','Pelajaran 2: Rasul Ulul Azmi', $sirahm$[{"n":1,"title":"رسول اولوا العزم","subtitle":"Rasul Ulul Azmi • pengenalan dan sifat sabar","icon":"🌟","cards":[{"q":"اڤاكه مقصود رسول اولوا العزم؟","a":"Rasul Ulul Azmi ialah para rasul yang memiliki keteguhan, kesabaran dan keazaman luar biasa.","tip":"Rasul Ulul Azmi ialah para rasul yang memiliki keteguhan, kesabaran dan keazaman luar biasa.","page":"29"},{"q":"براڤاكه بيلڠن رسول اولوا العزم؟","a":"Terdapat lima orang Rasul Ulul Azmi.","tip":"Terdapat lima orang Rasul Ulul Azmi.","page":"29"},{"q":"سياڤاكه انتارا رسول اولوا العزم؟","a":"Nabi Nuh, Ibrahim, Musa, Isa dan Muhammad ﷺ ialah Rasul Ulul Azmi.","tip":"Nabi Nuh, Ibrahim, Musa, Isa dan Muhammad ﷺ ialah Rasul Ulul Azmi.","page":"29"},{"q":"نبي محمد ﷺ جوڬ رسول اولوا العزم.","a":"Nabi Muhammad ﷺ termasuk dalam golongan Rasul Ulul Azmi.","tip":"Nabi Muhammad ﷺ termasuk dalam golongan Rasul Ulul Azmi.","page":"29"}]},{"n":2,"title":"كسه نبي نوح عليه السلام","subtitle":"Tauhid • bahtera • banjir besar","icon":"🚢","cards":[{"q":"نبي نوح عليه السلام منغاجق قومڽ مڽمبه الله.","a":"Nabi Nuh menyeru kaumnya supaya menyembah Allah Yang Esa.","tip":"Nabi Nuh menyeru kaumnya supaya menyembah Allah Yang Esa.","page":"29–30"},{"q":"قوم نبي نوح مڽمبه برهالا.","a":"Antara berhala yang disembah ialah Wadd, Suwa‘, Yaghuth, Ya‘uq dan Nasr.","tip":"Antara berhala yang disembah ialah Wadd, Suwa‘, Yaghuth, Ya‘uq dan Nasr.","page":"29–30"},{"q":"بڽق قوم نبي نوح منولق دعوه بلياو.","a":"Ramai kaumnya menolak seruan Nabi Nuh, namun baginda terus bersabar.","tip":"Ramai kaumnya menolak seruan Nabi Nuh, namun baginda terus bersabar.","page":"30–32"},{"q":"الله ممرينتهكن نبي نوح ممبينا بهاݢترا.","a":"Allah memerintahkan Nabi Nuh membina bahtera sebagai persediaan menghadapi banjir.","tip":"Allah memerintahkan Nabi Nuh membina bahtera sebagai persediaan menghadapi banjir.","page":"32–34"}]},{"n":3,"title":"كسه نبي إبراهيم عليه السلام","subtitle":"Menentang penyembahan berhala • api yang sejuk","icon":"🔥","cards":[{"q":"قوم نبي إبراهيم عليه السلام مڽمبه برهالا.","a":"Kaum Nabi Ibrahim menyembah berhala, sedangkan baginda mengajak mereka mentauhidkan Allah.","tip":"Kaum Nabi Ibrahim menyembah berhala, sedangkan baginda mengajak mereka mentauhidkan Allah.","page":"35–37"},{"q":"نبي إبراهيم مڠاجق قومڽ مڽمبه الله.","a":"Nabi Ibrahim mengajak kaumnya meninggalkan berhala dan menyembah Allah.","tip":"Nabi Ibrahim mengajak kaumnya meninggalkan berhala dan menyembah Allah.","page":"35–39"},{"q":"نبي إبراهيم ممرچيهكن برهالا قومڽ.","a":"Nabi Ibrahim menghancurkan berhala-berhala untuk menyedarkan kaumnya.","tip":"Nabi Ibrahim menghancurkan berhala-berhala untuk menyedarkan kaumnya.","page":"39–40"},{"q":"قوم نبي إبراهيم مڠهوقوم بلياو دڠن اڤي.","a":"Kaumnya mahu membakar Nabi Ibrahim kerana menentang berhala.","tip":"Kaumnya mahu membakar Nabi Ibrahim kerana menentang berhala.","page":"40–41"}]},{"n":4,"title":"كلوارݢ نبي إبراهيم","subtitle":"Hajar dan Ismail • Safa-Marwah • air Zamzam","icon":"💧","cards":[{"q":"نبي إبراهيم ممباوا هاجر دان إسماعيل ك ليمبه يڠ تندوس.","a":"Menurut buku teks, Nabi Ibrahim meninggalkan Hajar dan Ismail di kawasan yang tandus dengan perintah Allah.","tip":"Menurut buku teks, Nabi Ibrahim meninggalkan Hajar dan Ismail di kawasan yang tandus dengan perintah Allah.","page":"43"},{"q":"هاجر ممڤرتاوهكن كڤرچاياءنڽ كڤد الله.","a":"Hajar tetap bertawakal kepada Allah ketika berada di kawasan tandus.","tip":"Hajar tetap bertawakal kepada Allah ketika berada di kawasan tandus.","page":"43–44"},{"q":"هاجر برولڠ اليق انتارا بوكيت صفا دان مروة.","a":"Hajar berusaha mencari air dengan bergerak antara Safa dan Marwah.","tip":"Hajar berusaha mencari air dengan bergerak antara Safa dan Marwah.","page":"44"},{"q":"الله مڠورنياكن اير زمزم كڤد إسماعيل.","a":"Air Zamzam muncul dengan izin Allah ketika Hajar mencari air untuk Ismail.","tip":"Air Zamzam muncul dengan izin Allah ketika Hajar mencari air untuk Ismail.","page":"44–45"}]},{"n":5,"title":"كسه نبي موسى عليه السلام","subtitle":"Firaun • Sungai Nil • Bani Israel • laut terbelah","icon":"🌊","cards":[{"q":"نبي موسى عليه السلام هيدوڤ ڤد زمان فرعون.","a":"Nabi Musa hidup pada zaman pemerintahan Firaun.","tip":"Nabi Musa hidup pada zaman pemerintahan Firaun.","page":"46–47"},{"q":"ايبو نبي موسى مڠهاڽوتكن باييڽ د سوڠاي.","a":"Bayi Musa diletakkan di dalam bekas di Sungai Nil bagi menyelamatkannya daripada Firaun.","tip":"Bayi Musa diletakkan di dalam bekas di Sungai Nil bagi menyelamatkannya daripada Firaun.","page":"47–49"},{"q":"نبي موسى ممبسر د ايستان فرعون.","a":"Dengan aturan Allah, Nabi Musa dibesarkan di istana Firaun.","tip":"Dengan aturan Allah, Nabi Musa dibesarkan di istana Firaun.","page":"48–50"},{"q":"نبي موسى مڠاجق فرعون برايمن كڤد الله.","a":"Nabi Musa menyampaikan seruan Allah kepada Firaun dengan berani.","tip":"Nabi Musa menyampaikan seruan Allah kepada Firaun dengan berani.","page":"52–54"}]},{"n":6,"title":"كسه نبي عيسى عليه السلام","subtitle":"Maryam • kelahiran • Injil • mukjizat dan akidah","icon":"🕊️","cards":[{"q":"ايبو نبي عيسى عليه السلام برنام مريم.","a":"Maryam ialah ibu kepada Nabi Isa.","tip":"Maryam ialah ibu kepada Nabi Isa.","page":"57–60"},{"q":"نبي عيسى دلاهيركن تنڤا باڤا.","a":"Dengan kekuasaan Allah, Nabi Isa dilahirkan oleh Maryam tanpa bapa.","tip":"Dengan kekuasaan Allah, Nabi Isa dilahirkan oleh Maryam tanpa bapa.","page":"59–61"},{"q":"نبي عيسى بوليه برچاكڤ سواكتو بايي دڠن ايزين الله.","a":"Nabi Isa dapat berbicara semasa bayi sebagai salah satu mukjizat daripada Allah.","tip":"Nabi Isa dapat berbicara semasa bayi sebagai salah satu mukjizat daripada Allah.","page":"60–62"},{"q":"الله منورونكن كتاب انجيل كڤد نبي عيسى.","a":"Nabi Isa menerima kitab Injil sebagai wahyu daripada Allah.","tip":"Nabi Isa menerima kitab Injil sebagai wahyu daripada Allah.","page":"62–64"}]}]$sirahm$::jsonb, $sirahg$[{"n":1,"name":"🌟 Rasul Ulul Azmi","type":"clue","intro":"Pilih jawapan Jawi yang paling tepat berdasarkan kisah dalam buku teks.","steps":[["اڤاكه كأيستيميواءن رسول اولوا العزم؟",["صابار دان تڬوه","مو‌ده ڤوتوس اسا","سوكا برڬادوه","تيدق برتڠڬوڠجواب"],0,"Rasul Ulul Azmi ialah para rasul yang memiliki keteguhan, kesabaran dan keazaman luar biasa.","29","🌟"],["براڤاكه بيلڠن رسول اولوا العزم؟",["توجوه","ليما","تيڬا","سمبيلن"],1,"Terdapat lima orang Rasul Ulul Azmi.","29","🌟"],["سياڤاكه رسول اولوا العزم؟",["نبي هارون","نبي يونس","نبي نوح","نبي داود"],2,"Nabi Nuh, Ibrahim, Musa, Isa dan Muhammad ﷺ ialah Rasul Ulul Azmi.","29","🌟"],["اداكه نبي محمد ﷺ رسول اولوا العزم؟",["تيدق","هاني نبي ابراهيم","هاني نبي موسى","يا"],3,"Nabi Muhammad ﷺ termasuk dalam golongan Rasul Ulul Azmi.","29","🌟"],["باڬايمانا رسول اولوا العزم برهادڤن دوعاءن؟",["تتڤ تڬوه","مڽره","برتيدور","مڽمبوڽي"],0,"Mereka tabah berdakwah walaupun menghadapi pelbagai cabaran.","29","🌟"],["اڤاكه تلادن يڠ بوليه ديامبيل؟",["ڤوتوس اسا","صابار دان اوسها","مڠهينا اورڠ","ملاڠڬر امانه"],1,"Kita hendaklah berusaha dan bersabar apabila berhadapan kesukaran.","29","🌟"]]},{"n":2,"name":"🚢 Tauhid","type":"clue","intro":"Pilih jawapan Jawi yang paling tepat berdasarkan kisah dalam buku teks.","steps":[["كڤد سياڤاكه قوم نبي نوح ڤرلو مڽمبه؟",["برهالا","راج","الله","بيناتڠ"],2,"Nabi Nuh menyeru kaumnya supaya menyembah Allah Yang Esa.","29–30","🚢"],["اڤاكه ڤربواتن ساله قوم نبي نوح؟",["برصدقه","مڽمبه الله","ممبنتو اورڠ","مڽمبه برهالا"],3,"Antara berhala yang disembah ialah Wadd, Suwa‘, Yaghuth, Ya‘uq dan Nasr.","29–30","🚢"],["باڬايمانا سيكڤ نبي نوح كتيك دعوه دتولق؟",["تتڤ صابر","مڠهينا قوم","برهنتي دعوه","مڽراهن"],0,"Ramai kaumnya menolak seruan Nabi Nuh, namun baginda terus bersabar.","30–32","🚢"],["اڤاكه يڠ ديبينا اوليه نبي نوح؟",["استان","باهترا","منارا","ڤاسر"],1,"Allah memerintahkan Nabi Nuh membina bahtera sebagai persediaan menghadapi banjir.","32–34","🚢"],["اڤاكه يڠ برلاكو ڤد زمان نبي نوح؟",["کمراو ڤنجڠ","ݢمڤا بومي","بنجير بسر","ڤڽاكيت"],2,"Banjir besar berlaku selepas Nabi Nuh berdakwah dengan penuh kesabaran.","33–34","🚢"],["سياڤاكه يڠ دسلامتكن دالم بهاݢترا؟",["قوم يڠ منچچا","سموا ڤڽمبه برهالا","فرعون","نبي نوح دان اورڠ برايمن"],3,"Nabi Nuh dan orang beriman diselamatkan di dalam bahtera.","34","🚢"]]},{"n":3,"name":"🔥 Susun Peristiwa Nabi Ibrahim","type":"timeline","intro":"Susun jalan cerita Nabi Ibrahim mengikut urutan.","events":[["١","Ibrahim menyeru kaumnya menyembah Allah"],["٢","Baginda menghancurkan berhala"],["٣","Kaumnya mencampakkan baginda ke dalam api"],["٤","Allah menjadikan api sejuk dan selamat"]]},{"n":4,"name":"💧 Padankan Kisah Hajar","type":"build","intro":"Pilih kad lalu padankan dengan petunjuk kisah Hajar dan Ismail.","slots":[["👩","هاجر","Ibu Nabi Ismail"],["👦","إسماعيل","Anak Nabi Ibrahim"],["🏞️","صفا دان مروة","Dua bukit yang dilalui Hajar"],["💧","زمزم","Air yang dikurniakan oleh Allah"]]},{"n":5,"name":"🌊 Firaun","type":"clue","intro":"Pilih jawapan Jawi yang paling tepat berdasarkan kisah dalam buku teks.","steps":[["سياڤاكه ڤمرينته ظالم ڤد زمان نبي موسى؟",["فرعون","نمرود","جالوت","قارون"],0,"Nabi Musa hidup pada zaman pemerintahan Firaun.","46–47","🌊"],["د سوڠاي ماناكه بايي موسى دهاڽوتكن؟",["سوڠاي ڤاهڠ","سوڠاي نيل","سوڠاي كينتاباتڠن","سوڠاي ڤيراق"],1,"Bayi Musa diletakkan di dalam bekas di Sungai Nil bagi menyelamatkannya daripada Firaun.","47–49","🌊"],["د ماناكه نبي موسى ممبسر؟",["ڤاسر","ڬوا","ايستان فرعون","ڤولاو"],2,"Dengan aturan Allah, Nabi Musa dibesarkan di istana Firaun.","48–50","🌊"],["اڤاكه دعوه اوتام نبي موسى كڤد فرعون؟",["مڽمبه برهالا","منجاديكن فرعون توهن","منچاري هرتا","برايمن كڤد الله"],3,"Nabi Musa menyampaikan seruan Allah kepada Firaun dengan berani.","52–54","🌊"],["سياڤاكه قوم يڠ ديڤيمڤين اوليه نبي موسى؟",["بني إسرائيل","قوم عاد","قوم ثمود","قوم نبي نوح"],0,"Allah menolong Nabi Musa dan Bani Israel melarikan diri daripada penindasan Firaun.","54–56","🌊"],["اڤاكه معجزه نبي موسى كتيك دكجر فرعون؟",["مڠوبت ڤساكيت","ممبله لاوت","مڠهيدوڤكن اورڠ ماتي","مڠورونكن هوجن"],1,"Allah membelah laut sebagai mukjizat bagi menyelamatkan Nabi Musa dan Bani Israel.","55–56","🌊"]]},{"n":6,"name":"🕊️ Maryam","type":"clue","intro":"Pilih jawapan Jawi yang paling tepat berdasarkan kisah dalam buku teks.","steps":[["سياڤاكه ايبو نبي عيسى؟",["هاجر","اسيه","مريم","خديجه"],2,"Maryam ialah ibu kepada Nabi Isa.","57–60","🕊️"],["باڬايمانا نبي عيسى دلاهيركن؟",["دالم بهاݢترا","د ايستان","د ڤادڠ ڤاسير","تنڤا باڤا"],3,"Dengan kekuasaan Allah, Nabi Isa dilahirkan oleh Maryam tanpa bapa.","59–61","🕊️"],["اڤاكه معجزه نبي عيسى سواكتو بايي؟",["برچاكڤ","ممبله لاوت","ممبينا بهاݢترا","ممرچيه برهالا"],0,"Nabi Isa dapat berbicara semasa bayi sebagai salah satu mukjizat daripada Allah.","60–62","🕊️"],["اڤاكه نام كتاب يڠ دتورونكن كڤد نبي عيسى؟",["توراة","انجيل","زبور","صحف"],1,"Nabi Isa menerima kitab Injil sebagai wahyu daripada Allah.","62–64","🕊️"],["دڠن ايزين سياڤاكه معجزه نبي عيسى برلاكو؟",["فرعون","مريم","الله","راج"],2,"Mukjizat Nabi Isa berlaku dengan izin Allah, bukannya kuasa baginda sendiri.","63–65","🕊️"],["اڤاكه يڠ برلاكو كڤد نبي عيسى منوروت عقيدة اسلام؟",["دبونوه موسوه","تروه هيلڠ","دبakar","دسلامتكن دان دڠكت الله"],3,"Menurut kisah buku teks dan ayat al-Quran yang dipetik, Nabi Isa tidak dibunuh dan Allah mengangkat baginda.","65–69","🕊️"]]},{"n":7,"name":"🏆 BONUS — Jejak Rasul Ulul Azmi","type":"treasure","intro":"Uji semula enam kisah dan pengajaran utama daripada pelajaran ini.","steps":[["سياڤاكه رسول اولوا العزم؟",["نبي هارون","نبي يونس","نبي نوح","نبي داود"],2,"Nabi Nuh, Ibrahim, Musa, Isa dan Muhammad ﷺ ialah Rasul Ulul Azmi.","29","🌟"],["اڤاكه يڠ ديبينا اوليه نبي نوح؟",["استان","باهترا","منارا","ڤاسر"],1,"Allah memerintahkan Nabi Nuh membina bahtera sebagai persediaan menghadapi banjir.","32–34","🚢"],["اڤاكه يڠ الله جاديكن كڤد اڤي؟",["سجوک دان سلامت","لبـيه ڤانس","اد ڤتر","مڠهيلڠ"],0,"Dengan kuasa Allah, api menjadi sejuk dan selamat bagi Nabi Ibrahim.","41–42","🔥"],["عملن اڤاكه مڠيڠتكن كسه صفا دان مروة؟",["زكاة","اذان","اعتكاف","سعي"],3,"Peristiwa Safa dan Marwah menjadi pengajaran yang dikaitkan dengan amalan saie dalam haji.","44–45","💧"],["سياڤاكه ڤمرينته ظالم ڤد زمان نبي موسى؟",["فرعون","نمرود","جالوت","قارون"],0,"Nabi Musa hidup pada zaman pemerintahan Firaun.","46–47","🌊"],["باڬايمانا نبي عيسى دلاهيركن؟",["دالم بهاݢترا","د ايستان","د ڤادڠ ڤاسير","تنڤا باڤا"],3,"Dengan kekuasaan Allah, Nabi Isa dilahirkan oleh Maryam tanpa bapa.","59–61","🕊️"]]}]$sirahg$::jsonb, true)
